	*len = uncompressed;
	sc_log_hex(card->ctx, "Compressed data", from + 8, compressed);
	sc_log_hex(card->ctx, "Uncompressed data", upt, uncompressed);
 compress_exit:

#endif

	sc_log(card->ctx, "uncompress: returning with%s de-compression ",
	       (upt == from) ? "out" : "");
	return upt;
