			}
			if (r == SC_ERROR_INCORRECT_PARAMETERS)
				goto read_done;
			free(buffer);
			if (apdu.resp != tmp)
				free(apdu.resp);
			LOG_FUNC_RETURN(ctx, r);	/* arriving here means response error */
		}
